.ee-clickable { cursor: pointer; }
.ee-clickable:hover { color: var(--primary); }

script:
const container = root_element.querySelector(".ee-activity");
frappe.call({
    method: "expertedge.api.dashboard.get_recent_activity",
    callback: function(r) {
        if (!r.message || !r.message.length) {
            container.innerHTML = '<p style="color:var(--text-muted);">No recent activity</p>';
            return;
        }
        var html = '<div class="ee-act-title">Recent Activity</div>';
        r.message.forEach(function(a) {
            var dot_color = a.color || "grey";
            html += '<div class="ee-act-row" data-route="' + a.route + '">' +
                '<div class="ee-act-dot" style="background:var(--' + dot_color + '-500,var(--text-muted));"></div>' +
                '<div class="ee-act-body">' +
                '<div class="ee-act-text">' + frappe.utils.escape_html(a.text) +
                ' <span class="ee-act-badge" style="background:var(--' + dot_color + '-100,var(--control-bg));color:var(--' + dot_color + '-500,var(--text-muted));">' + frappe.utils.escape_html(a.detail) + '</span></div>' +
                '<div class="ee-act-time">' + a.ago + '</div>' +
                '</div></div>';
        });
        container.innerHTML = html;
        container.querySelectorAll(".ee-act-row").forEach(function(row) {
            row.addEventListener("click", function() {
                window.location.href = row.getAttribute("data-route");
            });
        });
    }
});

