script:
const container = root_element.querySelector(".ee-paylinks");
frappe.call({
    method: "expertedge.api.dashboard.get_payment_links_summary",
    callback: function(r) {
        if (!r.message) { container.innerHTML = '<p style="color:var(--text-muted);">No payment links yet</p>'; return; }
        var d = r.message;
        var statusColors = { Draft: "grey", Generated: "blue", Sent: "orange", Paid: "green", Expired: "red", Cancelled: "grey" };
        var html = '<div class="ee-pl-title">Payment Links</div>';

        // Summary pills
        if (d.summary && d.summary.length) {
            html += '<div class="ee-pl-pills">';
            d.summary.forEach(function(s) {
                var color = statusColors[s.status] || "grey";
                html += '<div class="ee-pl-pill" data-route="/app/ee-nomod-payment-link?status=' + encodeURIComponent(s.status) + '">' +
                    '<span class="ee-pl-dot" style="background:var(--' + color + '-500,var(--text-muted));"></span>' +
                    '<span class="ee-pl-status">' + s.status + '</span>' +
                    '<span class="ee-pl-count">' + s.count + '</span>' +
                    '<span class="ee-pl-amt">' + s.currency + ' ' + Number(s.total_amount).toLocaleString() + '</span>' +
                    '</div>';
            });
            html += '</div>';
        }

        // Recent list
        if (d.recent && d.recent.length) {
            html += '<div class="ee-pl-list">';
            d.recent.forEach(function(r) {
                var color = statusColors[r.status] || "grey";
                html += '<div class="ee-pl-row" data-route="/app/ee-nomod-payment-link/' + r.name + '">' +
                    '<div class="ee-pl-dot-sm" style="background:var(--' + color + '-500,var(--text-muted));"></div>' +
                    '<div class="ee-pl-info">' +
                    '<span class="ee-pl-name">' + frappe.utils.escape_html(r.candidate_name || r.name) + '</span>' +
                    '<span class="ee-pl-purpose">' + r.purpose + '</span>' +
                    '</div>' +
                    '<div class="ee-pl-right">' +
                    '<span class="ee-pl-amount">' + r.currency + ' ' + Number(r.amount).toLocaleString() + '</span>' +
                    '<span class="ee-pl-ago">' + r.ago + '</span>' +
                    '</div></div>';
            });
            html += '</div>';
        }

        container.innerHTML = html;
        container.querySelectorAll("[data-route]").forEach(function(el) {
            el.addEventListener("click", function() { window.location.href = el.getAttribute("data-route"); });
        });
    }
});

